package com.foodsupply.management.quality.service;
import com.foodsupply.management.common.exception.ResourceNotFoundException;import com.foodsupply.management.quality.dto.QualityInspectionRequest;import com.foodsupply.management.quality.entity.QualityInspection;import com.foodsupply.management.quality.repository.QualityInspectionRepository;import org.springframework.stereotype.Service;import java.util.List;
@Service public class QualityInspectionService {private final QualityInspectionRepository repository;public QualityInspectionService(QualityInspectionRepository r){repository=r;}
 public List<QualityInspection> findAll(){return repository.findAll();}public QualityInspection findById(Long id){return repository.findById(id).orElseThrow(()->new ResourceNotFoundException("Quality inspection",id));}
 public QualityInspection create(QualityInspectionRequest r){return repository.save(map(new QualityInspection(),r));}public QualityInspection update(Long id,QualityInspectionRequest r){return repository.save(map(findById(id),r));}public void delete(Long id){repository.delete(findById(id));}
 private QualityInspection map(QualityInspection q,QualityInspectionRequest r){q.setStockBatchId(r.stockBatchId());if(r.inspectionDate()!=null)q.setInspectionDate(r.inspectionDate());q.setResult(r.result());q.setWastageQuantity(r.wastageQuantity());q.setCorrectiveAction(r.correctiveAction());q.setInspectedBy(r.inspectedBy());return q;}}
